#!/usr/bin/env node
// Extract loaded-memory values from an ELF binary.
// Maps each PT_LOAD segment at BASE + p_vaddr and emits 4-byte
// little-endian words as { address: uint32 }.
'use strict';
const fs = require('fs');

const path = process.argv[2];
if (!path) {
  process.stderr.write('usage: node extract.js <binary>\n');
  process.exit(1);
}

const BASE = 0x400000; // load base for the (PIE) image
const buf = fs.readFileSync(path);

// --- Minimal ELF64 little-endian parsing (public file-format layout) ---
if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 ||
    buf[2] !== 0x4c || buf[3] !== 0x46) {
  process.stderr.write('not an ELF file\n');
  process.exit(1);
}
const ei_class = buf[4]; // 2 => ELF64
if (ei_class !== 2) {
  process.stderr.write('only ELF64 supported\n');
  process.exit(1);
}

const e_phoff = Number(buf.readBigUInt64LE(0x20));
const e_phentsize = buf.readUInt16LE(0x36);
const e_phnum = buf.readUInt16LE(0x38);

const PT_LOAD = 1;
const out = {};

for (let i = 0; i < e_phnum; i++) {
  const ph = e_phoff + i * e_phentsize;
  if (ph + 56 > buf.length) break;
  const p_type = buf.readUInt32LE(ph + 0);
  if (p_type !== PT_LOAD) continue;
  const p_offset = Number(buf.readBigUInt64LE(ph + 8));
  const p_vaddr = Number(buf.readBigUInt64LE(ph + 0x10));
  const p_filesz = Number(buf.readBigUInt64LE(ph + 0x20));

  // Emit 4-byte little-endian words for the file-backed content.
  for (let off = 0; off + 4 <= p_filesz; off += 4) {
    const fpos = p_offset + off;
    if (fpos + 4 > buf.length) break;
    const addr = BASE + p_vaddr + off;
    out[addr] = buf.readUInt32LE(fpos);
  }
}

process.stdout.write(JSON.stringify(out));
